#include <queue>
#include <vector>
#include <cmath>

class Solution {
public:
    int minimumOperationsToMakeEqual(int x, int y) {
        if (x <= y) return y - x;
        std::queue<std::pair<int, int>> q;
        std::vector<bool> vis(x + 15, false);
        q.push({x, 0});
        vis[x] = true;
        while (!q.empty()) {
            auto [v, steps] = q.front();
            q.pop();
            if (v == y) return steps;
            std::vector<int> nxts;
            if (v % 11 == 0) nxts.push_back(v / 11);
            if (v % 5 == 0) nxts.push_back(v / 5);
            nxts.push_back(v - 1);
            nxts.push_back(v + 1);
            for (int nxt : nxts) {
                if (nxt > 0 && nxt <= x + 11 && !vis[nxt]) {
                    vis[nxt] = true;
                    q.push({nxt, steps + 1});
                }
            }
        }
        return std::abs(x - y);
    }
};

import java.util.ArrayDeque;
import java.util.Queue;

class Solution {
    public int minimumOperationsToMakeEqual(int x, int y) {
        if (x <= y) return y - x;
        Queue<int[]> q = new ArrayDeque<>();
        boolean[] vis = new boolean[x + 15];
        q.add(new int[]{x, 0});
        vis[x] = true;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int v = cur[0], steps = cur[1];
            if (v == y) return steps;
            int[] nxts = new int[4];
            int count = 0;
            if (v % 11 == 0) nxts[count++] = v / 11;
            if (v % 5 == 0) nxts[count++] = v / 5;
            nxts[count++] = v - 1;
            nxts[count++] = v + 1;
            for (int i = 0; i < count; i++) {
                int nxt = nxts[i];
                if (nxt > 0 && nxt <= x + 11 && !vis[nxt]) {
                    vis[nxt] = true;
                    q.add(new int[]{nxt, steps + 1});
                }
            }
        }
        return Math.abs(x - y);
    }
}

